-- Tirados do editor no ar em 13/09/2026, nao do arquivo que estava no
-- repositorio. O arquivo estava velho: vinha da v295 e tinha 114 referencias
-- contra as 122 de hoje, 5 departamentos contra 7, 3 embalagens contra 4.
--
-- O grupo SUB entra antes de tudo porque a cor "SUBLIMACAO" pertence a ele e o
-- editor o trata como caso especial, fora da lista dos doze. Sem essa linha a
-- chave estrangeira recusa a cor, e como tudo roda numa transacao so, a carga
-- INTEIRA e desfeita em silencio: as tabelas ficam vazias e parece que nada
-- aconteceu. Foi exatamente o que aconteceu na primeira tentativa.

insert into public.grupo_de_cor (cod, nome, ordem)
values ('SUB', 'Sublimação', 14)
on conflict (cod) do nothing;

