from unnest(string_to_array('pagamento~ENTRADA + SAIDA~1§pagamento~LINK~2§pagamento~ENTRADA + BOLETO~3§pagamento~PIX TOTAL~4§pagamento~DINHEIRO~5§pagamento~BOLETO~6§pagamento~ENTREGA~7§pagamento~CARTAO DE CREDITO~8§pagamento~PATROCINIO~9§entrega~AEREO~1§entrega~CORREIOS~2§entrega~FABRICA~3§entrega~MOTOBOY~4§entrega~TRANSPORTADORA~5§embalagem~Fardo~1§embalagem~Sacola~2§embalagem~Caixa~3§embalagem~SACO CORREIOS~4§vendedor~Lucas~1§vendedor~Dani~2§vendedor~Kev~3§vendedor~Alam~4§vendedor~Fabricio~5§departamento~Sublimação~1§departamento~DTF~2§departamento~Silk~3§departamento~DTF + Sublimação~4§departamento~DTF + Silk~5§departamento~BORDADO~6§departamento~SILK + SUBLIMAÇÃO~7', '§')) as t(x);
